import{_ as e,o,c as a,a2 as r}from"./chunks/framework.BZO4qERu.js";const p=JSON.parse('{"title":"Выбор расширения","description":"","frontmatter":{},"headers":[],"relativePath":"ru/guides/extensions.md","filePath":"ru/guides/extensions.md","lastUpdated":1792323081000}'),d={name:"ru/guides/extensions.md"};function s(l,t,h,i,n,c){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="выбор-расширения" tabindex="-1">Выбор расширения <a class="header-anchor" href="#выбор-расширения" aria-label="Permalink to &quot;Выбор расширения&quot;">​</a></h1><p>В Memoh есть пять способов расширить возможности Bot. По названиям они звучат похоже, пока не поставить их рядом, — поэтому вот они, рядом.</p><table tabindex="0"><thead><tr><th>Расширение</th><th>Что это</th><th>Где живёт / как срабатывает</th><th>Для чего подходит</th></tr></thead><tbody><tr><td><a href="./skills.html">Навыки</a></td><td>Промпт-модули <code>SKILL.md</code>, меняющие то, как Bot себя ведёт</td><td>В рабочем пространстве Bot, в каталоге <code>/data/skills/</code>; управляются на вкладке <strong>Skills</strong>; вызываются в разговоре</td><td>Рутины и рабочие привычки, которые иначе приходилось бы набирать заново каждый раз</td></tr><tr><td><a href="./hooks.html">Hooks</a></td><td>Правила на события в <code>hooks.json</code>, которые запускают команды или инструменты</td><td>В <code>/data/.memoh/hooks.json</code>; редактируются на вкладке <strong>Hooks</strong>; срабатывают на событиях жизненного цикла вроде <code>PreToolUse</code> или <code>TurnEnd</code></td><td>Проверки и побочные действия в фиксированных точках, без участия чата</td></tr><tr><td><a href="./mcp.html">MCP</a></td><td>Подключения к внешним серверам инструментов MCP</td><td>Настраиваются для каждого Bot на вкладке <strong>MCP</strong> как Stdio- или Remote-подключение; обнаруженные инструменты используются в разговоре</td><td>Подключение инструмента, у которого уже есть свой MCP-сервер</td></tr><tr><td><a href="./../self-hosted/connectors.html">Коннекторы</a></td><td>OAuth- или API-key-привязки к сервисам вроде GitHub или Notion</td><td>Приходят как компоненты приложения (App); авторизуются и управляются на вкладке <strong>Apps</strong> Bot; инструменты сервиса появляются в разговоре</td><td>Чтобы Bot действовал от имени вашего аккаунта во внешнем сервисе</td></tr><tr><td><a href="./supermarket.html">Supermarket</a></td><td>Встроенный каталог Memoh: установка упакованных приложений в один клик — навыки вместе с их зависимостями и коннекторами</td><td>Открывается из боковой панели; установленное попадает в рабочее пространство целевого Bot и на его вкладку <strong>Apps</strong></td><td>Готовая возможность без сборки из отдельных частей</td></tr></tbody></table><p>Каким бы путём возможность ни пришла, сходится всё в одном месте: инструменты коннекторов и MCP появляются в разговоре рядом с инструментами рабочего пространства Bot, а установленные навыки отображаются на вкладке <strong>Skills</strong> так же, как написанные вручную.</p><h2 id="что-выбрать" tabindex="-1">Что выбрать? <a class="header-anchor" href="#что-выбрать" aria-label="Permalink to &quot;Что выбрать?&quot;">​</a></h2><ul><li>Изменить то, как Bot выполняет работу → <a href="./skills.html">навык</a>.</li><li>Автоматически делать что-то в фиксированный момент → <a href="./hooks.html">хук</a>.</li><li>Подключить инструмент, у которого есть MCP-сервер → <a href="./mcp.html">MCP</a>.</li><li>Разрешить Bot пользоваться вашим аккаунтом GitHub или Notion → <a href="./../self-hosted/connectors.html">коннектор</a>.</li><li>Установить готовый пакет в один клик → <a href="./supermarket.html">Supermarket</a>.</li></ul><div class="tip custom-block"><p class="custom-block-title">Они сочетаются</p><p>Это не конкурирующие варианты. Приложение, установленное из Supermarket, может принести навыки и коннекторы вместе, а хук может сторожить инструменты, пришедшие через MCP. Выбирайте по вопросу выше, а не «по одному на Bot».</p></div><h2 id="с-чего-начать" tabindex="-1">С чего начать <a class="header-anchor" href="#с-чего-начать" aria-label="Permalink to &quot;С чего начать&quot;">​</a></h2><p>У каждого варианта есть отдельная страница с деталями, которые эта таблица сжимает:</p><ul><li><a href="./skills.html">Навыки</a> — как писать <code>SKILL.md</code>, состояния навыков, принятие обнаруженных навыков.</li><li><a href="./hooks.html">Hooks</a> — каталог событий, схема конфигурации, тестирование правила.</li><li><a href="./mcp.html">MCP</a> — Stdio- и Remote-подключения, OAuth, обнаружение инструментов.</li><li><a href="./../self-hosted/connectors.html">Коннекторы</a> — статусы подключений, повторная авторизация, пространства имён инструментов.</li><li><a href="./supermarket.html">Supermarket</a> — просмотр каталога и установка в Bot.</li></ul><p>Если сомневаетесь, сначала загляните в Supermarket: установленный пакет покажет, как выглядит готовая конфигурация, прежде чем собирать собственную.</p>',11)])])}const u=e(d,[["render",s]]);export{p as __pageData,u as default};
